const state={files:[],settingsKey:'submission-prep-settings'};
const $=id=>document.getElementById(id);
const formatBytes=n=>n<1024?`${n} B`:n<1048576?`${(n/1024).toFixed(1)} KB`:`${(n/1048576).toFixed(2)} MB`;
const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
function renderFiles(){const list=$('fileList');$('fileCount').textContent=`${state.files.length}개`;if(!state.files.length){list.className='file-list empty';list.innerHTML='<div class="empty-state"><span>▧</span><p>아직 추가한 파일이 없습니다.</p><small>파일을 추가하면 이곳에서 순서를 바꿀 수 있어요.</small></div>';return}list.className='file-list';list.innerHTML=state.files.map((f,i)=>`<div class="file-row"><span class="file-icon">${f.type==='application/pdf'?'PDF':'IMG'}</span><div class="file-info"><div class="file-name" title="${esc(f.name)}">${esc(f.name)}</div><div class="file-meta">${formatBytes(f.size)} · ${f.type==='application/pdf'?'PDF':'이미지'}</div></div><div class="row-actions"><button class="icon-btn" aria-label="${i+1}번 파일 위로 이동" data-up="${i}" ${i===0?'disabled':''}>↑</button><button class="icon-btn" aria-label="${i+1}번 파일 아래로 이동" data-down="${i}" ${i===state.files.length-1?'disabled':''}>↓</button><button class="icon-btn" aria-label="${esc(f.name)} 삭제" data-remove="${i}">×</button></div></div>`).join('');list.querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>{const i=+b.dataset.up;[state.files[i-1],state.files[i]]=[state.files[i],state.files[i-1]];renderFiles()});list.querySelectorAll('[data-down]').forEach(b=>b.onclick=()=>{const i=+b.dataset.down;[state.files[i+1],state.files[i]]=[state.files[i],state.files[i+1]];renderFiles()});list.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{state.files.splice(+b.dataset.remove,1);renderFiles()})}
function addFiles(files){state.files.push(...[...files].filter(f=>f.type.startsWith('image/')||f.type==='application/pdf'));renderFiles()}
function getSettings(){return{format:$('format').value,maxSize:$('maxSize').value,prefix:$('prefix').value,startNumber:$('startNumber').value}}
function applySettings(s){if(!s)return;$('format').value=s.format||'any';$('maxSize').value=s.maxSize||'';$('prefix').value=s.prefix||'';$('startNumber').value=s.startNumber||1}
function inspect(){if(!state.files.length){$('resultSubtitle').textContent='먼저 제출할 파일을 추가해주세요.';return}const s=getSettings(),max=s.maxSize?Number(s.maxSize)*1048576:Infinity;let pass=0,warn=0,total=0;const rows=state.files.map((f,i)=>{total+=f.size;const issues=[];if(f.size>max)issues.push('용량 초과');if(s.format==='pdf'&&f.type!=='application/pdf')issues.push('PDF 필요');const name=s.prefix?`${s.prefix}_${String(Number(s.startNumber||1)+i).padStart(2,'0')}.${f.name.split('.').pop()}`:f.name;const ok=!issues.length;if(ok)pass++;else warn++;return{f,i,name,issues,ok}});$('summaryTitle').textContent=warn?'확인이 필요한 파일이 있습니다':'모든 파일이 조건을 통과했습니다';$('summaryDetail').textContent=`${state.files.length}개 파일을 검사했습니다 · ${formatBytes(total)}`;$('passCount').textContent=pass;$('warnCount').textContent=warn;$('totalSize').textContent=formatBytes(total);$('summary').querySelector('.summary-icon').className=`summary-icon ${warn?'warn':'pass'}`;$('summary').querySelector('.summary-icon').textContent=warn?'!':'✓';$('resultSubtitle').textContent=warn?'파일을 확인한 뒤 다운로드하세요.':'이제 제출할 파일을 다운로드할 수 있습니다.';$('downloadButton').disabled=false;$('resultTable').innerHTML='<div class="result-row head"><span>파일명</span><span>크기</span><span>변경 후</span><span>상태</span></div>'+rows.map(r=>`<div class="result-row"><span title="${esc(r.f.name)}">${esc(r.f.name)}</span><span>${formatBytes(r.f.size)}</span><span title="${esc(r.name)}">${esc(r.name)}</span><span class="status ${r.ok?'pass':'warn'}">${r.ok?'통과':r.issues.join(', ')}</span></div>`).join('');state.lastRows=rows}
async function download(){if(!state.lastRows||!state.lastRows.length)return;const s=getSettings();if(s.format==='pdf'){if(!window.jspdf){alert('PDF 기능을 불러오는 중입니다. 잠시 후 다시 시도해주세요.');return}const {jsPDF}=window.jspdf;const pdf=new jsPDF();let page=true;for(const row of state.lastRows){if(row.f.type.startsWith('image/')){const data=await readData(row.f);const img=await imageSize(data);const scale=Math.min(180/img.w,250/img.h);if(!page)pdf.addPage();pdf.addImage(data,'JPEG',15,15,img.w*scale,img.h*scale);page=false}}pdf.save((s.prefix||'제출파일')+'.pdf');return}if(s.format==='zip'&&window.JSZip){const zip=new JSZip();state.lastRows.forEach(r=>zip.file(r.name,r.f));const blob=await zip.generateAsync({type:'blob'});saveBlob(blob,(s.prefix||'제출파일')+'.zip');return}for(const r of state.lastRows){const name=s.prefix?`${s.prefix}_${String(Number(s.startNumber||1)+r.i).padStart(2,'0')}.${r.f.name.split('.').pop()}`:r.f.name;saveBlob(r.f,name)}}
function readData(file){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)})}function imageSize(src){return new Promise(res=>{const i=new Image();i.onload=()=>res({w:i.width,h:i.height});i.src=src})}function saveBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
$('fileInput').onchange=e=>addFiles(e.target.files);['dragenter','dragover'].forEach(ev=>$('dropzone').addEventListener(ev,e=>{e.preventDefault();$('dropzone').classList.add('dragging')}));['dragleave','drop'].forEach(ev=>$('dropzone').addEventListener(ev,e=>{e.preventDefault();$('dropzone').classList.remove('dragging')}));$('dropzone').ondrop=e=>addFiles(e.dataTransfer.files);$('checkButton').onclick=inspect;$('downloadButton').onclick=download;$('saveSettings').onclick=()=>{localStorage.setItem(state.settingsKey,JSON.stringify(getSettings()));alert('현재 제출 조건을 저장했습니다.')};$('loadSettings').onclick=()=>{const raw=localStorage.getItem(state.settingsKey);if(raw){applySettings(JSON.parse(raw));alert('저장한 제출 조건을 불러왔습니다.')}else alert('저장한 설정이 없습니다.')};$('resetButton').onclick=()=>{state.files=[];state.lastRows=null;renderFiles();$('resultSubtitle').textContent='파일을 추가하고 조건 검사하기를 눌러주세요.';$('downloadButton').disabled=true;$('resultTable').innerHTML='<div class="table-empty">검사 결과가 여기에 표시됩니다.</div>';$('summaryTitle').textContent='검사 대기 중';$('summaryDetail').textContent='아직 검사한 파일이 없습니다.';$('passCount').textContent='0';$('warnCount').textContent='0';$('totalSize').textContent='0 KB'};renderFiles();
